/* Molecules and salts share reference cards, but use different interaction rules. */
const cxEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cxPlainFormula=s=>({H3N:'NH3',ClH:'HCl',FH:'HF',BrH:'HBr',H3P:'PH3',H4Si:'SiH4'}[s]||s);
const cxFormula=s=>cxEscape(cxPlainFormula(s)).replace(/(\d+)/g,'<sub>$1</sub>');
const cxCharge=n=>n?(Math.abs(n)>1?Math.abs(n):'')+(n>0?'+':'−'):'0';
const cxQ=s=>document.querySelector(s);
let chemistryPhotos={};
Promise.all(['photo-index.json','photo-expansion.json'].map(file=>fetch('images/chemistry/'+file+'?v=9').then(r=>r.ok?r.json():{}).catch(()=>({})))).then(parts=>{chemistryPhotos=Object.assign({},...parts);cxRefreshPhotos()});
const molState={atoms:[],bonds:[],selected:null,electron:null,electronSlot:null,recipe:null,hint:null,history:[],zoom:1};
const saltState={atoms:[],selected:null,history:[],mode:'transfer',recipe:null};
const molBankState={query:'',category:'',page:0},saltBankState={query:'',category:'',page:0};
function chemistryScaffold(){
 cxQ('#molecules').innerHTML=`<div class="chem-title"><div><p class="eyebrow">03 / DEL ELEKTRONER</p><h2>Molekylverksted</h2><p>To elektroner. Ett felles par. En binding.</p></div><a href="#moleculeBank" class="chem-bank-link">Utforsk <span data-molecule-count></span> molekyler ↓</a></div>
 <div class="chem-steps"><span><b>1</b> Velg atomer</span><span><b>2</b> Par to blå elektroner</span><span><b>3</b> Oppdag molekylet</span></div>
 <div class="chem-workspace"><aside class="chem-palette"><h3>Byggesteiner</h3><p class="note">Tallet viser vanlige bindinger i denne modellen.</p><div class="chem-palette-grid">${Object.entries(chemElements).map(([s,v])=>`<button data-add-mol="${s}" title="Legg til ${v.name}"><strong style="--atom-color:${v.color}">${s}</strong><span>${v.name}</span><small>${v.bonds} binding${v.bonds>1?'er':''}</small></button>`).join('')}</div><details><summary>Modellen vi bruker</summary><p>Enkel Lewis-modell for nøytrale molekyler. H får to elektroner rundt seg, C, N, O og halogenene vanligvis åtte. Bor er et unntak med seks.</p><p>P vises med tre bindinger og S med to. Utvidet oktett, ioner, radikaler og metallkomplekser inngår ikke her. Elektronprikkene er bokføring, ikke elektronbaner. Strukturen kontrolleres, men ikke romlig geometri, stereokjemi eller om stoffet er stabilt under bestemte forhold.</p><a href="https://openstax.org/books/chemistry-2e/pages/7-3-lewis-symbols-and-structures" target="_blank" rel="noreferrer">Lewis-strukturer · OpenStax ↗</a></details></aside>
 <div class="chem-main"><div class="chem-toolbar"><div><button id="molUndo">↶ Angre</button><button id="molClear">Tøm</button><button id="molDelete" disabled>Fjern valgt atom</button></div><div><button id="molHydrogen">Fyll med H</button><label>Zoom <select id="molZoom"><option value="1">100 %</option><option value="0.75">75 %</option><option value="0.5">50 %</option><option value="0.3">30 %</option></select></label></div></div>
 <div class="chem-recipe" id="molRecipe"></div><p class="chem-instruction" id="molInstruction" role="status">Trykk på et blått elektron, og så et blått elektron på et annet atom. Du kan også dra mellom dem.</p>
 <div class="chem-viewport" id="molViewport" tabindex="0" aria-label="Arbeidsflate for molekyler. Rull for å utforske store molekyler."><div id="molExtent"><div id="molBoard" class="chem-board"><svg class="chem-lines" aria-label="Bindinger i molekylet" id="molLines"></svg><div id="molAtoms"></div></div></div></div>
 <div class="chem-board-footer"><span><i class="chem-blue"></i> Ledig elektron</span><span>•• Elektronpar som ikke binder</span><span>Trykk på en binding for å fjerne ett par.</span></div><p class="note">Dra et løst H-atom til et ledig elektron: det festes i den retningen. Bundne atomer flyttes samlet. Vann vises vinklet; metan vises som et symmetrisk 90°-kors i denne flate modellen, ikke som sin romlige tetraederform.</p><div id="molResult" aria-live="polite"></div></div></div>
 <section class="chem-bank" id="moleculeBank"><div class="chem-title"><div><p class="eyebrow">STOFFBANKEN</p><h2><span data-molecule-count></span> molekyler å utforske</h2><p>Vanlige stoffer og flere eksempler fra organisk kjemi, natur og hverdag.</p></div></div><div class="chem-bank-filters"><label>Søk i molekylbanken<input id="molSearch" type="search" placeholder="Navn, formel eller bruksområde"></label><label>Stoffgruppe<select id="molCategory"><option value="">Alle grupper</option></select></label></div><p id="molBankCount" class="note" role="status"></p><div id="molBankCards" class="chem-bank-grid"></div><div id="molPagination" class="chem-pagination"></div><div id="molReference" class="chem-reference" hidden></div></section>`;
 cxQ('#salts').innerHTML=`<div class="chem-title"><div><p class="eyebrow">04 / GI OG TA ELEKTRONER</p><h2>Saltverket</h2><p>Overfør elektroner. Dann ioner. Finn et forhold som gir null ladning.</p></div><a class="chem-bank-link" href="#saltBank">Utforsk <span data-salt-count></span> salter ↓</a></div>
 <div class="chem-steps"><span><b>1</b> Velg byggesteiner</span><span><b>2</b> Lag eller balanser ioner</span><span><b>3</b> Oppdag saltet</span></div>
 <div class="salt-mode"><button data-salt-mode="transfer" class="active">Overfør elektroner</button><button data-salt-mode="ions">Bygg med ferdige ioner</button></div><p id="saltModeNote" class="muted"></p>
 <div class="chem-workspace"><aside class="chem-palette" id="saltPalette"></aside><div class="chem-main"><div class="chem-toolbar"><div><button id="saltUndo">↶ Angre</button><button id="saltClear">Tøm</button><button id="saltResetElectrons">Nullstill overføringer</button></div><strong id="saltTotal" aria-live="polite"></strong></div><div class="chem-recipe" id="saltRecipe"></div><p class="chem-instruction" id="saltInstruction" role="status"></p><div class="salt-board" id="saltBoard"></div><div id="saltResult" aria-live="polite"></div><details><summary>Hvorfor blir dette et salt?</summary><p>Metallatomer kan avgi elektroner og bli positive ioner. Ikke-metallatomer kan ta opp elektroner og bli negative ioner. Motsatte ladninger tiltrekker hverandre. I et fast salt danner ionene et stort krystallgitter, ikke små, atskilte saltmolekyler.</p><p>Formelen viser det enkleste heltallsforholdet mellom ionene. MgCl₂ betyr ett magnesiumion for hver to kloridioner. Total ladning er +2 + 2 × (−1) = 0.</p><p>Elektronoverføringen er en pedagogisk modell, ikke en oppskrift på en kjemisk reaksjon. Salter med sammensatte ioner bygges i den andre modusen; bindingene inne i disse ionene er allerede på plass.</p><a href="https://openstax.org/books/chemistry-2e/pages/7-1-ionic-bonding" target="_blank" rel="noreferrer">Ionebinding · OpenStax ↗</a></details></div></div>
 <section id="saltBank" class="chem-bank"><div class="chem-title"><div><p class="eyebrow">STOFFBANKEN</p><h2><span data-salt-count></span> salter og ioneforbindelser</h2><p>Fra bordsalt til karbonater og sulfater.</p></div></div><div class="chem-bank-filters"><label>Søk i saltbanken<input id="saltSearch" type="search" placeholder="Navn, formel eller bruksområde"></label><label>Byggemåte<select id="saltFilter"><option value="">Alle</option><option value="transfer">Elektronoverføring</option><option value="ions">Ferdige ioner</option></select></label></div><p id="saltBankCount" class="note" role="status"></p><div id="saltBankCards" class="chem-bank-grid"></div><div id="saltPagination" class="chem-pagination"></div><div id="saltReference" class="chem-reference" hidden></div></section>`;
}
function cxPhoto(item,type){const key=cxPhotoKey(item,type);return `<div class="compound-photos" data-compound-photo="${cxEscape(key)}">${cxPhotoFigures(item.photo||chemistryPhotos[key])}</div>`}
function moleculeDrawing(m){const drawingAtoms=molHydrideLayout(m)||m.atoms;const pts=drawingAtoms.map(a=>({x:a.x,y:a.y})),xs=pts.map(a=>a.x),ys=pts.map(a=>a.y),minX=Math.min(...xs),minY=Math.min(...ys),dx=Math.max(...xs)-minX||1,dy=Math.max(...ys)-minY||1,scale=Math.min(250/dx,145/dy),p=pts.map(a=>({x:155+(a.x-minX-dx/2)*scale,y:95+(a.y-minY-dy/2)*scale}));let out='';m.bonds.forEach(([a,b,n])=>{const A=p[a],B=p[b],len=Math.hypot(B.x-A.x,B.y-A.y)||1;for(let i=0;i<n;i++){const d=(i-(n-1)/2)*3;out+=`<line x1="${A.x-(B.y-A.y)/len*d}" y1="${A.y+(B.x-A.x)/len*d}" x2="${B.x-(B.y-A.y)/len*d}" y2="${B.y+(B.x-A.x)/len*d}" stroke="#62766b" stroke-width="1.5"/>`}});p.forEach((a,i)=>{const s=m.atoms[i].element;out+=`<circle cx="${a.x}" cy="${a.y}" r="${s==='H'?5:8}" fill="${chemElements[s]?.color||'#ddd'}"/><text x="${a.x}" y="${a.y+3}" text-anchor="middle" font-size="${s==='H'?7:9}" fill="#183c3a">${s}</text>`});return`<svg class="chem-illustration" viewBox="0 0 310 190" role="img" aria-label="Forenklet todimensjonal struktur av ${cxEscape(m.name)}">${out}</svg>`}
function saltDrawing(s){return ionLatticeMarkup(s)+`<div class="salt-illustration" role="img" aria-label="Ionene i formelen for ${cxEscape(s.name)}">${[s.cation,s.anion].map((ion,k)=>`<div><span class="salt-ion ${k?'negative':'positive'}">${cxFormula(ion.symbol)}<sup>${cxCharge(ion.charge)}</sup></span><b>${s.ratio[k]} ${k?(s.ratio[k]>1?'negative':'negativt'):(s.ratio[k]>1?'positive':'positivt')} ion${s.ratio[k]>1?'er':''}</b></div>`).join('')}</div><p class="note">Skjematisk formelforhold. I et fast salt gjentas ionene i et tredimensjonalt krystallgitter.</p>`}
function referenceMarkup(item,type,success=false){if(item.referenceOnly==='ozone')return ozoneMarkup();return `<div class="chem-discovery ${success?'found':''}"><div class="chem-discovery-text"><p class="eyebrow">${success?'STOFF GJENKJENT':'BLI KJENT MED STOFFET'}</p><h3>${cxEscape(item.name)} <span>${cxFormula(item.formula)}</span></h3><p>${cxEscape(item.description)}</p>${item.teachingNote?`<p class="ozone-notice">${cxEscape(item.teachingNote)}</p>`:''}${cxFactPanel(item,type)}${type==='molecule'&&item.aliases?.length?`<p class="note">Samme atomkoblinger kan også beskrives med: ${item.aliases.map(cxEscape).join(', ')}. Verkstedet skiller ikke romlige isomerer.</p>`:''}${type==='molecule'?`<p class="note">${cxStructure(item)} Treffet gjelder atomkoblinger og bindingsorden, ikke stereokjemi. En korrekt Lewis-struktur er ikke alene et bevis på stabilitet.</p>`:`<p>${sodiumBalance(item)}</p>`}<a href="${cxEscape(item.source)}" target="_blank" rel="noreferrer">Fakta og struktur · kilde ↗</a></div><div class="chem-discovery-visual">${type==='molecule'?moleculeDrawing(item):saltDrawing(item)}${cxPhoto(item,type)}</div></div>`}
function cxStructure(m){const n=[1,2,3].map(order=>m.bonds.filter(b=>b[2]===order).length),labels=['enkeltbinding','dobbeltbinding','trippelbinding'];return `${m.atoms.length} ${m.atoms.length===1?'atom':'atomer'}, koblet med ${n.map((count,i)=>count?count+' '+labels[i]+(count>1?'er':''):'').filter(Boolean).join(', ')}. Bindingene inneholder totalt ${m.bonds.reduce((sum,b)=>sum+b[2],0)} ${m.bonds.reduce((sum,b)=>sum+b[2],0)===1?'delt elektronpar':'delte elektronpar'}.`}
function sodiumBalance(s){return `${s.ratio[0]} × (${s.cation.charge>0?'+':''}${s.cation.charge}) + ${s.ratio[1]} × (${s.anion.charge}) = 0. Formelen viser det enkleste forholdet ${s.ratio[0]}:${s.ratio[1]}.`}
function molSnapshot(){molState.history.push(JSON.stringify({atoms:molState.atoms,bonds:molState.bonds,recipe:molState.recipe}));if(molState.history.length>60)molState.history.shift()}
function molCommit(){molState.electron=null;molState.hint=null;renderMolecule();}
function molPositionAtoms(m){const symmetric=molHydrideLayout(m);if(symmetric)return symmetric;const xs=m.atoms.map(a=>a.x),ys=m.atoms.map(a=>a.y),minX=Math.min(...xs),minY=Math.min(...ys);const lengths=m.bonds.map(([a,b])=>Math.hypot(m.atoms[a].x-m.atoms[b].x,m.atoms[a].y-m.atoms[b].y)).filter(v=>v>0).sort((a,b)=>a-b);const scale=lengths.length?150/lengths[Math.floor(lengths.length/2)]:180;return m.atoms.map(a=>({element:a.element,x:100+(a.x-minX)*scale,y:100+(a.y-minY)*scale}))}
function prepareMolecule(index,answer=false){const m=moleculeBank[index];if(m.referenceOnly)return;molSnapshot();molState.atoms=molPositionAtoms(m);molState.bonds=answer?m.bonds.map(b=>[...b]):[];molState.recipe=index;molState.selected=null;const needed=Math.max(...molState.atoms.map(a=>a.x+85)),fit=cxQ('#molViewport').clientWidth/needed;molState.zoom=[1,.75,.5,.3].find(z=>z<=fit)||.3;cxQ('#molZoom').value=molState.zoom;molCommit();cxQ('#molViewport').scrollTo(0,0);molMessage(answer?'Fasit viser alle bindingene. Du kan fjerne et elektronpar eller endre strukturen.':'Par et blått elektron med et blått elektron på et annet atom. Bruk «Vis neste kobling» for et hint.');cxQ('#molecules').scrollIntoView({behavior:'smooth',block:'start'})}
function addMoleculeAtom(symbol){if(molState.atoms.length>=220){molMessage('Arbeidsflaten har plass til 220 atomer. Fjern noen før du legger til flere.');return}molSnapshot();const columns=Math.max(2,Math.floor(cxQ('#molViewport').clientWidth/molState.zoom/155));let i=0,x,y;do{x=100+(i%columns)*155;y=100+Math.floor(i/columns)*155;i++;}while(molState.atoms.some(a=>Math.hypot(a.x-x,a.y-y)<115));molState.atoms.push({element:symbol,x,y});molState.recipe=null;molCommit()}
function molMessage(text){cxQ('#molInstruction').textContent=text}
function pairElectrons(a,b,slotA=null,slotB=null,snapshot=true){if(!chemCanBond(molState.atoms,molState.bonds,a,b)){molMessage('Velg ledige elektroner på to ulike atomer. Maksimalt tre elektronpar kan deles mellom samme to atomer.');return}if(snapshot)molSnapshot();if(!molClaimBond(molState.atoms,molState.bonds,a,b,slotA,slotB)){molMessage('Bindingsplassen er opptatt. Velg et ledig elektron.');return}molCommit();const found=chemValidate(molState.atoms,molState.bonds).complete?chemFindMolecule(molState.atoms,molState.bonds,moleculeBank):null;molMessage(isOzoneComposition(molState.atoms)?'Se ozon-forklaringen under arbeidsflaten. Fylte bindingsplasser er ikke nok til å vise riktig ozonstruktur.':found?`Du har bygget ${found.name.toLowerCase()}! Forklaring og illustrasjon vises under arbeidsflaten.`:'Ett elektron fra hvert atom er nå et felles elektronpar. Par flere elektroner for å lage en dobbelt- eller trippelbinding.')}
function renderMoleculeLines(){const s=molState;let html='';s.bonds.forEach(([a,b,n],i)=>{const A=s.atoms[a],B=s.atoms[b],len=Math.hypot(B.x-A.x,B.y-A.y)||1,ux=(B.x-A.x)/len,uy=(B.y-A.y)/len;for(let k=0;k<n;k++){const d=(k-(n-1)/2)*7;html+=`<line x1="${A.x+ux*37-uy*d}" y1="${A.y+uy*37+ux*d}" x2="${B.x-ux*37-uy*d}" y2="${B.y-uy*37+ux*d}" stroke="#47695d" stroke-width="3"/>`}html+=`<g class="chem-bond-remove" role="button" tabindex="0" data-remove-bond="${i}" aria-label="Fjern ett elektronpar mellom ${s.atoms[a].element} ${a+1} og ${s.atoms[b].element} ${b+1}"><circle cx="${(A.x+B.x)/2}" cy="${(A.y+B.y)/2}" r="15" fill="#fff" stroke="#c4d6c6"/><text x="${(A.x+B.x)/2}" y="${(A.y+B.y)/2+4}" text-anchor="middle" font-size="12" fill="#40685d">${'•'.repeat(n*2)}</text></g>`});if(s.hint){const A=s.atoms[s.hint[0]],B=s.atoms[s.hint[1]];html+=`<line x1="${A.x}" y1="${A.y}" x2="${B.x}" y2="${B.y}" stroke="#c6952b" stroke-width="4" stroke-dasharray="7 7"/>`}cxQ('#molLines').innerHTML=html;cxQ('#molLines').querySelectorAll('[data-remove-bond]').forEach(b=>{const act=()=>{molSnapshot();const i=+b.dataset.removeBond;s.bonds[i][3]?.pop();s.bonds[i][4]?.pop();if(--s.bonds[i][2]===0)s.bonds.splice(i,1);molCommit()};b.onclick=act;b.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();act()}}})}
function renderMolecule(){if(typeof syncClassroomURL==='function')syncClassroomURL();molSyncPorts(molState.atoms,molState.bonds);const s=molState,used=chemBondCounts(s.atoms,s.bonds),width=Math.max(740,...s.atoms.map(a=>a.x+100)),height=Math.max(410,...s.atoms.map(a=>a.y+100));cxQ('#molBoard').style.cssText=`width:${width}px;height:${height}px;transform:scale(${s.zoom});transform-origin:top left`;cxQ('#molExtent').style.cssText=`width:${width*s.zoom}px;height:${height*s.zoom}px`;cxQ('#molLines').setAttribute('viewBox',`0 0 ${width} ${height}`);cxQ('#molLines').style.height=height+'px';cxQ('#molAtoms').innerHTML=s.atoms.map((a,i)=>{const el=chemElements[a.element],free=el.bonds-used[i],lone=(el.valence-el.bonds)/2;let dots='';for(let k=0;k<el.bonds;k++){const angle=molAngles(a.element)[k]*Math.PI/180,x=49+49*Math.cos(angle),y=49+49*Math.sin(angle),available=molFreeSlots(s.atoms,s.bonds,i).includes(k);dots+=`<button class="chem-electron ${!available?'paired':''} ${s.electron===i&&s.electronSlot===k&&available?'chosen':''}" data-mol-electron="${i}" data-mol-slot="${k}" style="left:${x}px;top:${y}px" ${!available?'disabled':''} aria-label="${available?'Par elektron':'Elektron i binding'} ${k+1} på ${el.name} ${i+1}"><span></span></button>`}for(let k=0;k<lone;k++){const angle=molLoneAngles(a.element)[k]*Math.PI/180;dots+=`<span class="chem-lone-pairs" style="left:${49+47*Math.cos(angle)}px;top:${49+47*Math.sin(angle)}px" aria-label="Ett fritt elektronpar"><i>••</i></span>`;}return `<div class="chem-atom ${s.selected===i?'selected':''} ${s.hint?.includes(i)?'hinted':''}" data-mol-atom="${i}" style="left:${a.x-49}px;top:${a.y-49}px;--atom-color:${el.color}"><button class="chem-atom-core" data-mol-core="${i}" aria-label="${el.name} ${i+1}, ${used[i]} bindinger, ${free} ledige elektroner"><b>${a.element}</b><small>${i+1}</small></button>${dots}</div>`}).join('');renderMoleculeLines();cxQ('#molUndo').disabled=!s.history.length;cxQ('#molDelete').disabled=s.selected===null;cxQ('#molRecipe').innerHTML=s.recipe!==null?`<div><b>Oppgave: ${cxEscape(moleculeBank[s.recipe].name)}</b><span>${cxFormula(moleculeBank[s.recipe].formula)} · Atomene er plassert som støtte. Koble dem sammen.</span></div><button id="molHint">Vis neste kobling</button><button id="molAnswer">Vis fasit</button>`:`<div><b>Fri bygging</b><span>Start selv, eller velg en oppgave i stoffbanken.</span></div><button id="molWater">Prøv vann</button>`;if(s.recipe!==null){cxQ('#molHint').onclick=()=>{const m=moleculeBank[s.recipe],next=m.bonds.find(([a,b,n])=>(s.bonds.find(v=>(v[0]===a&&v[1]===b)||(v[0]===b&&v[1]===a))?.[2]||0)<n);s.hint=next?[next[0],next[1]]:null;renderMolecule();molMessage(next?`Par et ledig elektron på atom ${next[0]+1} (${m.atoms[next[0]].element}) med et på atom ${next[1]+1} (${m.atoms[next[1]].element}). Den gule linjen er et hint, ikke en binding.`:'Alle oppskriftens bindinger er på plass. Hvis treffet mangler, fjern eventuelle ekstra bindinger.')};cxQ('#molAnswer').onclick=()=>prepareMolecule(s.recipe,true)}else cxQ('#molWater').onclick=()=>{const i=moleculeBank.findIndex(m=>m.cid===962);if(i>=0)prepareMolecule(i)};
 cxQ('#molAtoms').querySelectorAll('[data-mol-electron]').forEach(b=>b.onclick=()=>{if(suppressChemClick){suppressChemClick=false;return}const i=+b.dataset.molElectron,slot=+b.dataset.molSlot;if(s.electron===null){s.electron=i;s.electronSlot=slot;renderMolecule();cxQ(`[data-mol-electron="${i}"]:not(:disabled)`)?.focus({preventScroll:true});molMessage(`Elektron på ${s.atoms[i].element} ${i+1} er valgt. Velg et ledig elektron på et annet atom.`)}else if(s.electron===i){s.electron=null;renderMolecule();molMessage('Valget er opphevet. Velg to ulike atomer.')}else pairElectrons(s.electron,i,s.electronSlot,slot)});
 cxQ('#molAtoms').querySelectorAll('[data-mol-core]').forEach(b=>{b.onclick=()=>{if(suppressChemClick){suppressChemClick=false;return}s.selected=+b.dataset.molCore;renderMolecule()};b.onkeydown=ev=>{const delta={ArrowLeft:[-15,0],ArrowRight:[15,0],ArrowUp:[0,-15],ArrowDown:[0,15]}[ev.key];if(!delta)return;ev.preventDefault();molSnapshot();const i=+b.dataset.molCore;molComponent(s.bonds,i).forEach(j=>{s.atoms[j].x+=delta[0];s.atoms[j].y+=delta[1]});molKeepOnBoard(s.atoms);renderMolecule();cxQ(`[data-mol-core="${i}"]`).focus()}});renderMoleculeResult();if(s.electron===null)molMessage(s.hint?`Par et ledig elektron på atom ${s.hint[0]+1} (${s.atoms[s.hint[0]].element}) med et på atom ${s.hint[1]+1} (${s.atoms[s.hint[1]].element}). Den gule linjen er et hint, ikke en binding.`:isOzoneComposition(s.atoms)?'Tre oksygenatomer: se ozon og modellforklaringen under arbeidsflaten.':chemValidate(s.atoms,s.bonds).complete?'Bindingsplassene er fylt. Se resultatet under arbeidsflaten.':'Trykk på et blått elektron, og så et blått elektron på et annet atom. Du kan også dra mellom dem.');}
function renderMoleculeResult(){const host=cxQ('#molResult');if(!host)return;if(isOzoneComposition(molState.atoms)){host.innerHTML=ozoneMarkup(molState.bonds);return}const check=chemValidate(molState.atoms,molState.bonds);let found=check.complete?chemFindMolecule(molState.atoms,molState.bonds,moleculeBank):null;host.innerHTML=found?referenceMarkup(found,'molecule',true)+moleculeIsomerFeedback(found):`<div class="chem-feedback"><b>${molState.atoms.length?cxFormula(chemFormula(molState.atoms)):'Hva vil du bygge?'}</b><p>${cxEscape(check.message)}</p>${check.complete?'<p>Ingen eksakt struktur i stoffbanken. Dette betyr ikke at stoffet er umulig; banken er et utvalg. Samme formel kan tilhøre flere ulike molekyler.</p>'+moleculeIsomerFeedback(null)+'':''}</div>`;}
function fillHydrogen(){const s=molState;molSyncPorts(s.atoms,s.bonds);const slots=s.atoms.map((_,i)=>molFreeSlots(s.atoms,s.bonds,i)),missing=slots.reduce((n,v)=>n+v.length,0);if(!s.atoms.length)return molMessage('Legg til et atom først.');if(s.atoms.length+missing>220)return molMessage('For mange H-atomer til arbeidsflaten.');if(!missing)return molMessage('Alle bindingsplasser er allerede fylt.');molSnapshot();slots.forEach((free,i)=>free.forEach(slot=>{const at=s.atoms.length;s.atoms.push({element:'H',...molPoint(s.atoms[i],slot)});s.bonds.push([i,at,1,[slot],[0]])}));molKeepOnBoard(s.atoms);s.recipe=null;molCommit();molMessage('Hydrogenatomene er plassert i retningene til de ledige valenselektronene. Bruk Angre for å gå tilbake.')}

function saltSnapshot(){saltState.history.push(JSON.stringify({atoms:saltState.atoms,mode:saltState.mode,recipe:saltState.recipe}));if(saltState.history.length>60)saltState.history.shift()}
function saltMessage(text){cxQ('#saltInstruction').textContent=text}
function saltAtom(symbol){const el=saltElements[symbol];return{symbol:el.symbol||symbol,transition:!!el.transition,name:el.name,charge:0,target:el.target,kind:el.target>0?'metal':'nonmetal',valence:el.valence}}
function saltAdd(symbol){if(saltState.atoms.length>=36)return saltMessage('Arbeidsflaten har plass til 36 atomer eller ioner.');saltSnapshot();saltState.atoms.push(saltAtom(symbol));saltState.recipe=null;saltState.selected=null;renderSalt()}
function saltIonAdd(ion){if(saltState.atoms.length>=36)return saltMessage('Arbeidsflaten har plass til 36 ioner.');saltSnapshot();saltState.atoms.push({...ion,target:ion.charge,kind:'ion'});renderSalt()}
function prepareSalt(index,answer=false){const item=saltBank[index];saltSnapshot();saltState.mode=item.mode;saltState.recipe=index;saltState.selected=null;saltState.atoms=[];if(item.mode==='transfer'||answer)[item.cation,item.anion].forEach((ion,i)=>{for(let k=0;k<item.ratio[i];k++)saltState.atoms.push(item.mode==='transfer'?saltAtom(saltElementKey(ion.symbol,ion.charge)):{...ion,target:ion.charge,kind:'ion'})});if(answer)saltState.atoms.forEach(a=>a.charge=a.target);renderSalt();if(item.mode==='ions')[item.cation,item.anion].forEach((ion,k)=>{const ions=[...new Map(saltBank.map(s=>{const a=k?s.anion:s.cation;return[a.symbol+':'+a.charge,a]})).values()];cxQ('#saltIon'+k).value=ions.findIndex(a=>a.symbol===ion.symbol&&a.charge===ion.charge)});saltMessage(answer?'Fasit viser det balanserte ioneforholdet.':item.mode==='transfer'?'Velg et blått elektron hos metallet, og så en stiplet plass hos ikke-metallet.':'De riktige ionslagene er valgt. Legg til positive og negative ioner til ladningene balanserer.');cxQ('#salts').scrollIntoView({behavior:'smooth',block:'start'})}
function transferElectron(from,to){const atoms=saltState.atoms,a=atoms[from],b=atoms[to];if(!a||!b||a.kind!=='metal'||b.kind!=='nonmetal'||a.charge>=a.target||b.charge<=b.target)return saltMessage('Velg et ledig elektron på et metall, og deretter en ledig plass på et ikke-metall.');saltSnapshot();saltTransfer(atoms,from,to);saltState.selected=null;renderSalt();const found=saltMatch(atoms,saltBank);saltMessage(found?`Du har laget ${found.name.toLowerCase()}! Les om saltet under ionene.`:`Ett elektron er overført fra ${a.name.toLowerCase()} til ${b.name.toLowerCase()}. Ladningene er nå ${cxCharge(a.charge)} og ${cxCharge(b.charge)}.`)}
function saltElectronClick(i){if(suppressChemClick){suppressChemClick=false;return}const a=saltState.atoms[i];if(a.kind==='metal'&&a.charge<a.target){saltState.selected=i;renderSalt();saltMessage(`Elektron fra ${a.name.toLowerCase()} er valgt. Trykk på en stiplet plass hos et ikke-metall.`)}else if(a.kind==='nonmetal'&&saltState.selected!==null)transferElectron(saltState.selected,i);else saltMessage('Start med et elektron på et metall. Det positive ionet avgir elektroner; det negative tar imot.')}
function renderSaltPalette(){const host=cxQ('#saltPalette'),chosen=[cxQ('#saltIon0')?.value,cxQ('#saltIon1')?.value];if(saltState.mode==='transfer'){host.innerHTML=`<h3>Metaller gir fra seg</h3><p class="note">Jern og kobber kan danne ulike ioner. Velg ønsket sluttladning. Prikkene viser elektronene som overføres i denne modellen, ikke hele elektronskallet.</p><div class="chem-palette-grid">${Object.entries(saltElements).filter(([,v])=>v.target>0).map(([s,v])=>`<button data-add-salt="${s}"><strong>${v.symbol||s}</strong><span>${v.name}</span><small>gir ${v.target} e⁻</small></button>`).join('')}</div><h3>Ikke-metaller tar imot</h3><div class="chem-palette-grid">${Object.entries(saltElements).filter(([,v])=>v.target<0).map(([s,v])=>`<button data-add-salt="${s}"><strong>${s}</strong><span>${v.name}</span><small>tar ${-v.target} e⁻</small></button>`).join('')}</div>`;host.querySelectorAll('[data-add-salt]').forEach(b=>b.onclick=()=>saltAdd(b.dataset.addSalt));}else{const positive=[...new Map(saltBank.map(s=>[s.cation.symbol+':'+s.cation.charge,s.cation])).values()],negative=[...new Map(saltBank.map(s=>[s.anion.symbol+':'+s.anion.charge,s.anion])).values()];host.innerHTML=`<h3>Ferdige ioner</h3><p class="note">Disse har allerede ladning. Legg til ioner til totalen blir null.</p>${[positive,negative].map((ions,k)=>`<label>${k?'Negativt':'Positivt'} ion<select id="saltIon${k}">${ions.map((a,i)=>`<option value="${i}">${cxEscape(a.name)} · ${cxEscape(a.symbol)} ${cxCharge(a.charge)}</option>`).join('')}</select></label><button id="saltAddIon${k}" class="wide">Legg til ${k?'negativt':'positivt'} ion</button>`).join('')}<p class="note">Inne i sammensatte ioner som SO₄²⁻ deler atomene elektroner. Ionebindingen i saltet virker mellom hele ioner.</p>`;[positive,negative].forEach((ions,k)=>{if(chosen[k]!==undefined)cxQ('#saltIon'+k).value=chosen[k];cxQ('#saltAddIon'+k).onclick=()=>saltIonAdd(ions[+cxQ('#saltIon'+k).value])});}}
function renderSalt(){const s=saltState;cxQ('#saltResetElectrons').hidden=s.mode!=='transfer';cxQ('#saltResetElectrons').disabled=!s.atoms.some(a=>a.charge!==0);if(typeof syncClassroomURL==='function')syncClassroomURL();document.querySelectorAll('[data-salt-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.saltMode===s.mode);b.setAttribute('aria-pressed',b.dataset.saltMode===s.mode)});cxQ('#saltModeNote').textContent=s.mode==='transfer'?'Trykk på et blått elektron hos metallet, og så en stiplet plass hos ikke-metallet. Du kan også dra elektronet over.':'Velg ferdige positive og negative ioner. Finn antallet som balanserer ladningene. Her overfører du ikke elektroner.';renderSaltPalette();cxQ('#saltUndo').disabled=!s.history.length;const total=saltCharge(s.atoms);cxQ('#saltTotal').innerHTML=`Total ladning: <span class="${total?'unbalanced':'balanced'}">${total>0?'+':''}${total}</span>`;cxQ('#saltRecipe').innerHTML=s.recipe!==null?`<div><b>Oppgave: ${cxEscape(saltBank[s.recipe].name)}</b><span>${cxFormula(saltBank[s.recipe].formula)} · ${s.mode==='transfer'?'Overfør elektronene for å danne ioner.':'Legg til ionene og finn riktig forhold.'}</span></div>${s.mode==='transfer'?'<button id="saltHint">Vis neste overføring</button>':''}<button id="saltAnswer">Vis fasit</button>`:'<div><b>Fri bygging</b><span>Alle atomer må bli ferdige ioner, og total ladning må være null.</span></div><div><button id="saltRust">Bygg jernoksid · rustmodell</button><button id="saltNaCl">Prøv bordsalt</button></div>';if(s.recipe!==null&&s.mode==='transfer'){cxQ('#saltHint').onclick=()=>{const a=s.atoms.findIndex(a=>a.kind==='metal'&&a.charge<a.target),b=s.atoms.findIndex(a=>a.kind==='nonmetal'&&a.charge>a.target);if(a>=0&&b>=0){s.selected=a;renderSalt();saltMessage(`Flytt ett elektron fra ${s.atoms[a].name} ${a+1} til ${s.atoms[b].name} ${b+1}.`)}else saltMessage('Alle nødvendige overføringer er fullført.')};cxQ('#saltAnswer').onclick=()=>prepareSalt(s.recipe,true)}if(s.recipe!==null&&s.mode==='ions')cxQ('#saltAnswer').onclick=()=>prepareSalt(s.recipe,true);else if(s.recipe===null){cxQ('#saltNaCl').onclick=()=>prepareSalt(saltBank.findIndex(s=>s.formula==='NaCl'));cxQ('#saltRust').onclick=()=>prepareSalt(saltBank.findIndex(s=>s.id==='fe2o3'));}
 cxQ('#saltBoard').innerHTML=s.atoms.length?s.atoms.map((a,i)=>{const complete=a.charge===a.target;let dots='';if(a.kind!=='ion'){const count=a.kind==='metal'?a.valence:8,present=a.valence-a.charge;for(let k=0;k<count;k++){const empty=k>=present,available=a.kind==='metal'?!empty:empty;dots+=`<button class="salt-electron ${empty?'empty':''} ${a.kind==='nonmetal'&&k>=a.valence&&!empty?'received':''} ${s.selected===i?'chosen':''}" data-salt-electron="${i}" ${!available?'disabled':''} aria-label="${a.kind==='metal'?'Overfør elektron':'Ta imot elektron'} ${k+1}, ${cxEscape(a.name)} ${i+1}"><span>${empty?'+':'•'}</span></button>`}}
 return`<div class="salt-atom ${complete?'complete':''} ${s.selected===i?'selected':''}"><button class="salt-remove" data-remove-salt="${i}" aria-label="Fjern ${cxEscape(a.name)} ${i+1}">×</button><p class="eyebrow">${a.kind==='metal'?'METALL':a.kind==='nonmetal'?'IKKE-METALL':'FERDIG ION'} ${i+1}</p><div class="salt-symbol ${a.charge>0?'positive':a.charge<0?'negative':''}">${cxFormula(a.symbol)}${a.charge?`<sup>${cxCharge(a.charge)}</sup>`:''}</div><strong>${cxEscape(a.name)}</strong><div class="salt-electrons">${dots}</div><p>${a.kind==='ion'?`Ladning ${cxCharge(a.charge)}`:a.kind==='metal'?`${a.charge} av ${a.target} ${a.target===1?'elektron':'elektroner'} avgitt`:`${-a.charge} av ${-a.target} ${a.target===-1?'elektron':'elektroner'} mottatt`}</p>${a.kind==='metal'&&complete?(a.transition?'<small>Valgt ion er dannet. Overgangsmetaller følger ikke den enkle regelen om fullt ytterste skall.</small>':'<small>Opprinnelige valenselektroner er avgitt. Skallet innenfor er nå ytterst og fullt.</small>'):a.kind==='nonmetal'?`<small>${a.valence-a.charge} elektroner i ytterste skall</small>`:''}</div>`}).join(''):'<div class="chem-empty"><b>Bygg et salt</b><p>Legg til et metall og et ikke-metall, eller prøv en oppgave fra stoffbanken.</p></div>';cxQ('#saltBoard').querySelectorAll('[data-salt-electron]').forEach(b=>b.onclick=()=>saltElectronClick(+b.dataset.saltElectron));cxQ('#saltBoard').querySelectorAll('[data-remove-salt]').forEach(b=>b.onclick=()=>{saltSnapshot();s.atoms.splice(+b.dataset.removeSalt,1);s.recipe=null;s.selected=null;renderSalt()});renderSaltResult();if(s.selected===null)saltMessage(s.mode==='transfer'?'Trykk på et blått elektron hos et metall, og så en stiplet plass hos et ikke-metall.':'Legg til positive og negative ioner til total ladning blir null.');}
function renderSaltResult(){const host=cxQ('#saltResult');if(!host)return;const s=saltState,match=saltMatch(s.atoms,saltBank),charge=saltCharge(s.atoms),unfinished=s.atoms.some(a=>a.charge!==a.target);host.innerHTML=match?referenceMarkup(match,'salt',true):`<div class="chem-feedback"><b>${s.atoms.length?'Ikke et ferdig treff ennå':'Klar for elektronoverføring?'}</b><p>${!s.atoms.length?'Velg byggesteiner til venstre.':charge&&s.mode==='transfer'?'Arbeidsflaten har mistet ladningsbalansen etter at et ion ble fjernet. Bruk «Nullstill overføringer» for å beholde atomene og starte fra nøytrale atomer, eller Angre for å hente tilbake ionet.':unfinished?'Noen atomer trenger fortsatt å avgi eller ta imot elektroner. Null total ladning alene er ikke nok.':charge?`Ioneblandingen har total ladning ${charge>0?'+':''}${charge}. Legg til eller fjern ioner for å få null.`:'Ionene er balansert, men denne kombinasjonen er ikke et treff i banken. Det betyr ikke at forbindelsen er umulig. Banken gjenkjenner ett positivt og ett negativt ionslag om gangen.'}</p></div>`}
function renderChemBank(type){const isMol=type==='molecule',bank=isMol?moleculeBank:saltBank,state=isMol?molBankState:saltBankState,prefix=isMol?'mol':'salt',q=state.query.toLocaleLowerCase('nb').replace(/[₀₁₂₃₄₅₆₇₈₉]/g,c=>'₀₁₂₃₄₅₆₇₈₉'.indexOf(c));const rows=bank.map((m,i)=>({m,i})).filter(({m})=>(!state.category||(isMol?m.category:m.mode)===state.category)&&[m.name,m.formula,cxPlainFormula(m.formula),m.description,cxFactSearch(m,type),...(m.aliases||[])].join(' ').toLocaleLowerCase('nb').includes(q));const pages=Math.max(1,Math.ceil(rows.length/18));state.page=Math.min(state.page,pages-1);cxQ('#'+prefix+'BankCount').textContent=`${rows.length} treff · side ${state.page+1} av ${pages}`;cxQ('#'+prefix+'BankCards').innerHTML=rows.slice(state.page*18,(state.page+1)*18).map(({m,i})=>`<article class="chem-bank-card"><div class="chem-bank-card-formula">${cxFormula(m.formula)}</div><h3>${cxEscape(m.name)}</h3><p>${cxEscape(isMol?m.category:m.mode==='transfer'?'Elektronoverføring':'Ferdige ioner')}</p><div><button data-chem-info="${i}">Utforsk</button>${m.referenceOnly?'':`<button data-chem-prepare="${i}">${isMol?'Gjør klar atomene':'Bygg selv'}</button>`}</div></article>`).join('')||'<p>Ingen treff. Prøv et annet navn eller en formel.</p>';cxQ('#'+prefix+'BankCards').querySelectorAll('[data-chem-info]').forEach(b=>b.onclick=()=>{const i=+b.dataset.chemInfo,host=cxQ('#'+prefix+'Reference');host.hidden=false;if(bank[i].referenceOnly){host.innerHTML=referenceMarkup(bank[i],type);host.scrollIntoView({behavior:'smooth',block:'start'});return}host.innerHTML=referenceMarkup(bank[i],type)+`<div class="chem-reference-actions"><button id="${prefix}ReferenceBuild">${isMol?'Gjør klar atomene':'Åpne i saltverket'}</button>${isMol?'<button id="molReferenceAnswer">Vis ferdig struktur</button>':''}</div>`;cxQ('#'+prefix+'ReferenceBuild').onclick=()=>isMol?prepareMolecule(i):prepareSalt(i);if(isMol)cxQ('#molReferenceAnswer').onclick=()=>prepareMolecule(i,true);host.scrollIntoView({behavior:'smooth',block:'start'})});cxQ('#'+prefix+'BankCards').querySelectorAll('[data-chem-prepare]').forEach(b=>b.onclick=()=>isMol?prepareMolecule(+b.dataset.chemPrepare):prepareSalt(+b.dataset.chemPrepare));cxQ('#'+prefix+'Pagination').innerHTML=`<button data-page="-1" ${state.page===0?'disabled':''}>← Forrige</button><span>${state.page+1} / ${pages}</span><button data-page="1" ${state.page>=pages-1?'disabled':''}>Neste →</button>`;cxQ('#'+prefix+'Pagination').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.page+=+b.dataset.page;renderChemBank(type);cxQ('#'+prefix+'BankCount').scrollIntoView({behavior:'smooth',block:'start'})})}
