function setupChemistry(){chemistryScaffold();document.querySelectorAll('[data-molecule-count]').forEach(e=>e.textContent=moleculeBank.length);document.querySelectorAll('[data-salt-count]').forEach(e=>e.textContent=saltBank.length);cxQ('#molCategory').innerHTML+=[...new Set(moleculeBank.map(m=>m.category))].sort().map(c=>`<option>${cxEscape(c)}</option>`).join('');document.querySelectorAll('[data-add-mol]').forEach(b=>b.onclick=()=>addMoleculeAtom(b.dataset.addMol));cxQ('#molClear').onclick=()=>{molSnapshot();Object.assign(molState,{atoms:[],bonds:[],selected:null,recipe:null});molCommit();molMessage('Arbeidsflaten er tømt. Velg atomer eller en oppgave.')};cxQ('#molUndo').onclick=()=>{if(!molState.history.length)return;Object.assign(molState,JSON.parse(molState.history.pop()),{selected:null});molCommit()};cxQ('#molDelete').onclick=()=>{const i=molState.selected;if(i===null)return;molSnapshot();molState.atoms.splice(i,1);molState.bonds=molState.bonds.filter(([a,b])=>a!==i&&b!==i).map(([a,b,n,...ports])=>[a>i?a-1:a,b>i?b-1:b,n,...ports]);molState.recipe=null;molState.selected=null;molCommit()};cxQ('#molHydrogen').onclick=fillHydrogen;cxQ('#molZoom').onchange=ev=>{molState.zoom=+ev.target.value;renderMolecule()};cxQ('#molSearch').oninput=ev=>{molBankState.query=ev.target.value;molBankState.page=0;renderChemBank('molecule')};cxQ('#molCategory').onchange=ev=>{molBankState.category=ev.target.value;molBankState.page=0;renderChemBank('molecule')};cxQ('#saltSearch').oninput=ev=>{saltBankState.query=ev.target.value;saltBankState.page=0;renderChemBank('salt')};cxQ('#saltFilter').onchange=ev=>{saltBankState.category=ev.target.value;saltBankState.page=0;renderChemBank('salt')};cxQ('#saltResetElectrons').onclick=()=>{saltSnapshot();resetSaltTransfers(saltState);renderSalt();saltMessage('Alle elektronoverføringer er nullstilt. Atomene er beholdt og er nøytrale igjen.');};cxQ('#saltClear').onclick=()=>{saltSnapshot();saltState.atoms=[];saltState.recipe=null;saltState.selected=null;renderSalt()};cxQ('#saltUndo').onclick=()=>{if(!saltState.history.length)return;Object.assign(saltState,JSON.parse(saltState.history.pop()),{selected:null});renderSalt()};document.querySelectorAll('[data-salt-mode]').forEach(b=>b.onclick=()=>{if(saltState.mode===b.dataset.saltMode)return;saltSnapshot();saltState.mode=b.dataset.saltMode;saltState.atoms=[];saltState.recipe=null;saltState.selected=null;renderSalt();saltMessage('Ny arbeidsflate. Den forrige byggingen kan hentes tilbake med Angre.')});
 document.addEventListener('pointerdown',ev=>{const electron=ev.target.closest('[data-mol-electron]:not(:disabled),[data-salt-electron]:not(:disabled)'),core=ev.target.closest('[data-mol-core]');if(!electron&&!core)return;suppressChemClick=false;const source=electron||core;chemDrag={type:core?'move':source.dataset.molElectron!==undefined?'bond':'transfer',index:Number(core?source.dataset.molCore:source.dataset.molElectron??source.dataset.saltElectron),x:ev.clientX,y:ev.clientY,moved:false,source};chemDrag.slot=source.dataset.molSlot===undefined?null:+source.dataset.molSlot;if(core){chemDrag.atom={...molState.atoms[chemDrag.index]};chemDrag.component=molComponent(molState.bonds,chemDrag.index);chemDrag.positions=molState.atoms.map(a=>({...a}));}});
 document.addEventListener('pointermove',ev=>{if(!chemDrag)return;const d=chemDrag,dx=ev.clientX-d.x,dy=ev.clientY-d.y;if(Math.hypot(dx,dy)<7&&!d.moved)return;ev.preventDefault();if(!d.moved){if(d.type==='move')molSnapshot();d.moved=true;}if(d.type==='move'){d.component.forEach(i=>{molState.atoms[i].x=d.positions[i].x+dx/molState.zoom;molState.atoms[i].y=d.positions[i].y+dy/molState.zoom;const node=cxQ(`[data-mol-atom="${i}"]`);node.style.left=(molState.atoms[i].x-49)+'px';node.style.top=(molState.atoms[i].y-49)+'px'});const rect=cxQ('#molBoard').getBoundingClientRect();d.snap=molFindSnap(molState.atoms,molState.bonds,d.index,{x:(ev.clientX-rect.left)/molState.zoom,y:(ev.clientY-rect.top)/molState.zoom});cxQ('#molSnapPreview')?.remove();document.querySelectorAll('.snap-target').forEach(el=>el.classList.remove('snap-target'));if(d.snap){const preview=document.createElement('div');preview.id='molSnapPreview';preview.textContent='H';preview.style.left=d.snap.x+'px';preview.style.top=d.snap.y+'px';cxQ('#molBoard').append(preview);cxQ(`[data-mol-electron="${d.snap.atom}"][data-mol-slot="${d.snap.slot}"]`)?.classList.add('snap-target')}renderMoleculeLines()}else{let ghost=cxQ('#chemDragGhost');if(!ghost){ghost=document.createElement('div');ghost.id='chemDragGhost';ghost.textContent='e⁻';document.body.append(ghost)}ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';}}, {passive:false});
 document.addEventListener('pointerup',ev=>{if(!chemDrag)return;const d=chemDrag;chemDrag=null;cxQ('#chemDragGhost')?.remove();if(!d.moved)return;suppressChemClick=true;setTimeout(()=>suppressChemClick=false,0);if(d.type==='move'){cxQ('#molSnapPreview')?.remove();document.querySelectorAll('.snap-target').forEach(el=>el.classList.remove('snap-target'));molState.selected=d.index;if(d.snap){molState.atoms[d.index]={...d.positions[d.index]};pairElectrons(d.index,d.snap.atom,0,d.snap.slot,false)}else{molKeepOnBoard(molState.atoms);renderMolecule()}return}const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest(d.type==='bond'?'[data-mol-electron]:not(:disabled)':'[data-salt-electron]:not(:disabled)');if(target){if(d.type==='bond')pairElectrons(d.index,+target.dataset.molElectron,d.slot,+target.dataset.molSlot);else transferElectron(d.index,+target.dataset.saltElectron)}else if(d.type==='bond')molMessage('Slipp på et ledig blått elektron på et annet atom. Du kan også trykke på de to elektronene etter tur.');else saltMessage('Slipp elektronet på en stiplet plass hos et ikke-metall.')});
 document.addEventListener('pointercancel',()=>{if(chemDrag?.type==='move'){molState.atoms=chemDrag.positions;if(chemDrag.moved)molState.history.pop();renderMolecule()}cxQ('#molSnapPreview')?.remove();document.querySelectorAll('.snap-target').forEach(el=>el.classList.remove('snap-target'));chemDrag=null;cxQ('#chemDragGhost')?.remove()});
 renderMolecule();renderSalt();renderChemBank('molecule');renderChemBank('salt');saltMessage('Legg til et metall og et ikke-metall, eller velg «Prøv bordsalt».');}
